from pathlib import Path
import subprocess, sys, json
p=Path('products/invoice-preflight'); p.mkdir(parents=True,exist_ok=True)
code='''import csv, json, sys
from decimal import Decimal, InvalidOperation
from datetime import date

def check(path):
    issues=[]
    seen=set()
    count=0
    with open(path, newline='', encoding='utf-8-sig') as f:
        reader=csv.DictReader(f)
        required={'invoice_id','customer','invoice_date','currency','amount'}
        fields=reader.fieldnames or []
        missing=required-set(fields)
        if missing:
            return {'rows':0,'valid':False,'issues':[{'row':1,'message':'Missing columns: '+', '.join(sorted(missing))}]}
        if len(fields)!=len(set(fields)):
            return {'rows':0,'valid':False,'issues':[{'row':1,'message':'Duplicate column names'}]}
        for row in reader:
            count+=1
            line=reader.line_num
            def flag(message): issues.append({'row':line,'message':message})
            if None in row or any(v is None for v in row.values()):
                flag('Column count differs from header')
                continue
            row={k:v.strip() for k,v in row.items()}
            for key in sorted(required):
                if not row[key]: flag('Empty '+key)
            key=row['invoice_id']
            if key in seen: flag('Repeated invoice_id; review whether these are legitimate invoice lines')
            if key: seen.add(key)
            try:
                value=Decimal(row['amount'])
                if not value.is_finite(): flag('Amount must be finite')
            except InvalidOperation: flag('Invalid decimal amount; use an ungrouped decimal such as 1234.50')
            try:
                value=row['invoice_date']
                if len(value)!=10 or date.fromisoformat(value).isoformat()!=value: raise ValueError()
            except ValueError: flag('Invalid invoice_date; expected YYYY-MM-DD')
            currency=row['currency']
            if len(currency)!=3 or not currency.isascii() or not currency.isalpha() or not currency.isupper(): flag('Currency must be three uppercase ASCII letters; actual currency membership is not checked')
    if count==0: issues.append({'row':1,'message':'No invoice rows'})
    return {'rows':count,'valid':not issues,'issues':issues}

if __name__=='__main__':
    try:
        result=check(sys.argv[1])
        print(json.dumps(result,indent=2))
        sys.exit(0 if result['valid'] else 1)
    except (OSError,UnicodeError,csv.Error,IndexError) as error:
        print(json.dumps({'valid':False,'error':str(error)}))
        sys.exit(2)
'''
(p/'preflight.py').write_text(code)
(p/'example.csv').write_text('invoice_id,customer,invoice_date,currency,amount\nINV-001,Example Customer,2026-10-31,USD,125.50\n')
(p/'invalid.csv').write_text('invoice_id,customer,invoice_date,currency,amount\nINV-001,,2026-02-30,usd,NaN\nINV-001,Example,2026-10-31,USD,12\n')
(p/'README.md').write_text('''# Invoice CSV Preflight — experimental prototype
Runs locally with Python 3; no dependencies or uploads.

Usage: python3 preflight.py example.csv

Required columns: invoice_id, customer, invoice_date, currency, amount.
This prototype assumes one row per invoice. Repeated identifiers require review and may be legitimate in line-item exports. Dates must use YYYY-MM-DD; amounts must be finite ungrouped decimals. Currency checks validate format only. Extra named columns are accepted.

Exit codes: 0 passes these checks; 1 review needed; 2 input error.
Passing does not establish accounting correctness or compatibility with any importer. No platform-specific mappings, tax checks, payment collection or revenue evidence exist yet. Keep original files; this tool never modifies inputs.

Commercial hypothesis: users facing failed invoice imports may pay for importer-specific mappings and validation. Demand and pricing remain unverified. Free prototype; paid customization is a proposed future offer.
''')
results=[]
for name,expected in [('example.csv',0),('invalid.csv',1)]:
    r=subprocess.run([sys.executable,str(p/'preflight.py'),str(p/name)],capture_output=True,text=True)
    assert r.returncode==expected,(name,r.stdout,r.stderr)
    data=json.loads(r.stdout)
    if name=='invalid.csv': assert len(data['issues'])==4,data
    results.append({'fixture':name,'exit_code':r.returncode,'report':data})
(p/'test-results.json').write_text(json.dumps({'tests_passed':True,'results':results},indent=2))
print(json.dumps({'product':str(p),'fixture_tests_passed':True,'revenue_verified':False}))
